R = {
    "cochinita-pibil": ("Cochinita pibil", "Messico", "4 h (+ 1 notte di marinatura)", "8 persone",
        "Il maiale sfilacciato dello Yucatán: marinato nell’achiote e negli agrumi, poi cotto lentamente in foglie di banano finché si scioglie.",
        ["2 kg di spalla di maiale a pezzi grossi", "100 g di pasta di achiote (annatto)", "Il succo di 4 arance e 2 lime, 4 spicchi d’aglio, 1 cucchiaino di origano e di cumino, sale", "Foglie di banano", "Tortillas di mais, cipolla rossa marinata nel succo di lime e peperoncino habanero per servire"],
        ["Sciogliere l’achiote nel succo di arancia e lime con l’aglio schiacciato, l’origano, il cumino e il sale.", "Ricoprire il maiale con questa marinata e lasciarlo una notte in frigorifero.", "Foderare una teglia con foglie di banano passate sulla fiamma, adagiarvi il maiale con la marinata e richiudere le foglie.", "Coprire con carta stagnola e cuocere in forno a 160 °C per 4 ore, finché la carne si sfilaccia con una forchetta.", "Sfilacciare il maiale nel suo sugo e servirlo in tortillas calde con la cipolla marinata e il peperoncino."]),
    "tamales": ("Tamales di pollo", "Messico", "2 h 30", "6 persone",
        "I fagottini di pasta di mais del Messico, ripieni di pollo in salsa piccante e cotti al vapore nelle foglie di mais.",
        ["500 g di farina di mais per tamales (masa)", "20 foglie di mais essiccate", "500 g di pollo cotto sfilacciato", "1 scatola di peperoncini chipotle in salsa adobo (o salsa verde)", "150 g di strutto o grasso vegetale, 500 ml di brodo di pollo, 1 cucchiaino di lievito per dolci, sale"],
        ["Mettere a bagno le foglie di mais in acqua calda per 30 minuti.", "Montare il grasso finché diventa chiaro, poi aggiungere la masa, il lievito, il sale e il brodo a poco a poco, fino a un impasto morbido di cui una pallina galleggi nell’acqua.", "Mescolare il pollo con i peperoncini chipotle tritati e un po’ della loro salsa.", "Spalmare 2 cucchiaiate di impasto su ogni foglia, aggiungere un cucchiaio di pollo e ripiegare i lati e poi il fondo.", "Cuocere in piedi al vapore per 1 h 15, finché l’impasto si stacca bene dalla foglia."]),
    "gallo-pinto": ("Gallo pinto", "Costa Rica e Nicaragua", "30 min", "4 persone",
        "La colazione dell’America centrale: riso del giorno prima saltato con fagioli neri, cipolla, peperone e coriandolo.",
        ["2 tazze di fagioli neri cotti, con un po’ del loro liquido", "3 tazze di riso bianco cotto il giorno prima", "1 cipolla e 1 peperone rosso tritati, 2 spicchi d’aglio", "1 mazzetto di coriandolo", "2 cucchiai d’olio, sale; salsa Lizano o Worcestershire a piacere"],
        ["Rosolare la cipolla, il peperone e l’aglio nell’olio per 5 minuti.", "Aggiungere i fagioli con il loro liquido e lasciar ridurre 3 minuti.", "Aggiungere il riso e mescolare delicatamente finché prende il colore dei fagioli.", "Condire con sale e un goccio di salsa Lizano.", "Cospargere di coriandolo e servire con uova, platano maturo fritto e panna acida."]),
    "mangu": ("Mangú", "Repubblica Dominicana", "40 min", "4 persone",
        "Il purè di platano verde dominicano, coperto di cipolla rossa all’aceto e servito con i «tre colpi»: salame, formaggio fritto e uovo.",
        ["4 platani verdi", "2 cipolle rosse ad anelli", "3 cucchiai di burro", "Aceto, olio, sale", "Formaggio da friggere, salame e uova per servire"],
        ["Sbucciare i platani, tagliarli a pezzi e lessarli 20 minuti in acqua salata.", "Rosolare le cipolle in un po’ d’olio e aggiungere un goccio d’aceto e sale.", "Schiacciare i platani con il burro e un po’ di acqua di cottura fredda fino a un purè liscio.", "Friggere le fette di salame e di formaggio e cuocere le uova.", "Servire il purè coperto di cipolla, con il salame, il formaggio e le uova."]),
    "patacones": ("Patacones", "Colombia", "30 min", "4 persone",
        "Dischi di platano verde fritti due volte, croccanti, con hogao (salsa di pomodoro e cipollotto) e avocado.",
        ["3 platani verdi", "Olio per friggere", "Sale e 1 spicchio d’aglio schiacciato in una ciotola d’acqua", "Hogao: 2 pomodori, 4 cipollotti, olio, sale", "1 avocado"],
        ["Sbucciare i platani e tagliarli a tocchetti di 4 cm.", "Friggerli 5 minuti in olio a media temperatura senza dorarli, poi scolarli.", "Schiacciarli tra due taglieri o con il fondo di un bicchiere e immergerli nell’acqua all’aglio salata.", "Friggerli di nuovo in olio ben caldo finché sono dorati e croccanti; salare.", "Hogao: cuocere i pomodori e i cipollotti tritati nell’olio per 10 minuti. Servire con l’avocado schiacciato."]),
    "bolon-verde": ("Bolón de verde", "Ecuador", "40 min", "4 persone",
        "Le palle di platano verde della costa dell’Ecuador, schiacciate con formaggio e ciccioli di maiale e dorate in padella.",
        ["4 platani verdi", "150 g di formaggio da griglia o mozzarella a cubetti", "150 g di chicharrón (ciccioli di maiale) o pancetta", "2 cucchiai di burro o strutto", "½ cucchiaino di achiote (annatto), sale"],
        ["Tagliare i platani a pezzi e lessarli 20 minuti in acqua salata.", "Rosolare il maiale a pezzetti e conservare il grasso.", "Schiacciare i platani caldi con il burro, l’achiote e un po’ del grasso.", "Aggiungere il formaggio e il maiale e formare palle grandi come un’arancia.", "Dorarle in padella con un filo d’olio. Servire a colazione con un uovo e un caffè."]),
    "yuca-mojo": ("Yuca con mojo", "Cuba", "45 min", "4 persone",
        "La manioca alla cubana: lessata finché è tenera e condita con un mojo caldo di aglio, agrumi e cipolla.",
        ["1 kg di manioca (yuca), fresca o surgelata", "8 spicchi d’aglio", "Il succo di 2 arance e 2 lime", "1 cipolla ad anelli sottili", "100 ml di olio d’oliva, 1 cucchiaino di cumino, sale"],
        ["Sbucciare la manioca, tagliarla a pezzi e togliere la fibra centrale.", "Lessarla 25-30 minuti in acqua salata, finché si apre; scolare.", "Schiacciare l’aglio con il sale e il cumino e stemperarlo nel succo di arancia e lime.", "Scaldare l’olio, ammorbidirvi la cipolla 3 minuti e versare il composto all’aglio fuori dal fuoco.", "Versare il mojo caldo sulla manioca e servire con maiale arrosto, o con riso e fagioli."]),
    "sopa-quinoa": ("Zuppa di quinoa", "Perù e Bolivia", "45 min", "6 persone",
        "La zuppa delle Ande: quinoa, patate e verdure in un brodo profumato all’ají, con formaggio fresco.",
        ["200 g di quinoa ben sciacquata", "3 patate e 2 carote a cubetti", "1 cipolla, 2 spicchi d’aglio, 1 cucchiaio di pasta di ají (o paprika)", "2 litri di brodo di pollo o vegetale, 1 tazza di piselli o fave", "Coriandolo o prezzemolo, formaggio fresco a cubetti, sale"],
        ["Rosolare la cipolla, l’aglio e l’ají in un po’ d’olio per 5 minuti.", "Aggiungere il brodo e la quinoa; cuocere 15 minuti.", "Aggiungere le patate e le carote; cuocere 15 minuti.", "Aggiungere i piselli o le fave, cuocere ancora 5 minuti e salare.", "Servire con coriandolo tritato e qualche cubetto di formaggio fresco."]),
    "ful-medames": ("Ful medames", "Egitto", "20 min", "4 persone",
        "La colazione dell’Egitto: fave cotte lentamente e schiacciate con aglio, cumino, limone e olio d’oliva.",
        ["2 scatole di fave (ful) da 400 g", "2 spicchi d’aglio, 1 cucchiaino di cumino, sale", "Il succo di 1 limone", "4 cucchiai di olio d’oliva", "Pomodoro, prezzemolo, cipolla, uova sode e pane pita per servire"],
        ["Scaldare le fave con il loro liquido 10 minuti a fuoco basso.", "Schiacciare l’aglio con il sale e il cumino.", "Schiacciare grossolanamente una parte delle fave, aggiungere l’aglio e il succo di limone, e un po’ d’acqua calda se troppo denso.", "Versare in un piatto fondo e condire abbondantemente con olio d’oliva.", "Guarnire con pomodoro e prezzemolo tritati, cipolla e uovo sodo; servire con pane pita caldo."]),
    "chorba-frik": ("Chorba frik", "Algeria", "1 h 15", "6 persone",
        "La zuppa del Ramadan in Algeria: agnello, pomodoro e grano verde spezzato, profumati al coriandolo e alla menta.",
        ["500 g di agnello a pezzetti", "100 g di frik (grano verde spezzato)", "1 scatola di ceci", "2 pomodori grattugiati e 1 cucchiaio di concentrato di pomodoro", "1 cipolla, 1 mazzetto di coriandolo, menta secca, cannella, paprika, sale, pepe"],
        ["Rosolare l’agnello e la cipolla tritata in un po’ d’olio con la cannella, la paprika, il sale e il pepe.", "Aggiungere i pomodori, il concentrato, metà del coriandolo tritato e 2 litri d’acqua; cuocere 40 minuti.", "Aggiungere i ceci scolati e il frik a pioggia; cuocere 20 minuti mescolando di tanto in tanto.", "Aggiungere il resto del coriandolo e un pizzico di menta secca.", "Servire con uno spicchio di limone, datteri e pane."]),
    "misir-wat": ("Misir wat", "Etiopia", "45 min", "4 persone",
        "Lo stufato etiope di lenticchie rosse al berberè, rosso e piccante, servito sull’injera.",
        ["250 g di lenticchie rosse", "2 cipolle rosse tritate finissime", "2 cucchiai di berberè (o peperoncino in polvere con paprika e spezie)", "3 spicchi d’aglio", "1 pezzo di zenzero, 4 cucchiai d’olio o burro chiarificato, sale"],
        ["Cuocere le cipolle senza grassi a fuoco basso per 10 minuti, mescolando, finché si ammorbidiscono.", "Aggiungere l’olio, l’aglio e lo zenzero grattugiati, poi il berberè; cuocere 3 minuti.", "Aggiungere le lenticchie sciacquate e 750 ml d’acqua.", "Cuocere 25 minuti a fuoco basso, mescolando, finché le lenticchie si disfano; salare.", "Servire con injera, pane o riso."]),
    "githeri-chapati": ("Githeri e chapati", "Kenya", "1 h 30", "6 persone",
        "Il piatto di tutti i giorni in Kenya: mais e fagioli stufati con pomodoro e verdure, con chapati sfogliati.",
        ["2 tazze di mais bianco secco e 1 tazza di fagioli rossi, in ammollo per una notte (o in scatola)", "2 pomodori, 1 cipolla, 1 carota, 1 patata", "Chapati: 500 g di farina", "1 cucchiaino di sale, 1 cucchiaio di zucchero, 300 ml di acqua tiepida", "Olio, 1 cucchiaino di curry, sale"],
        ["Lessare il mais e i fagioli ammollati per 1 ora, finché sono teneri; scolare.", "Rosolare la cipolla, la carota e la patata a cubetti nell’olio, aggiungere i pomodori e il curry, poi il mais e i fagioli; stufare 15 minuti.", "Chapati: impastare la farina, il sale, lo zucchero, 2 cucchiai d’olio e l’acqua per 10 minuti e lasciar riposare 30 minuti.", "Stendere l’impasto, spennellarlo d’olio, arrotolarlo a cilindro e poi a spirale; lasciar riposare e stendere in dischi sottili.", "Cuocere i chapati in una padella asciutta, ungendoli d’olio da entrambi i lati, finché sono dorati. Servire con il githeri."]),
    "salade-fonio": ("Insalata di fonio", "Senegal e Mali", "30 min", "4 persone",
        "Il fonio, cereale antico del Sahel, cotto in chicchi leggeri e servito in un’insalata fresca con verdure e limone.",
        ["250 g di fonio", "1 cetriolo e 2 pomodori a cubetti", "1 cipolla rossa e 1 peperone tritati", "Il succo di 2 limoni, 4 cucchiai d’olio", "Menta e prezzemolo, sale, pepe"],
        ["Sciacquare il fonio più volte e scolarlo bene.", "Cuocerlo al vapore 10 minuti (oppure versarlo in 400 ml di acqua bollente salata, coprire e lasciarlo gonfiare 5 minuti fuori dal fuoco).", "Sgranarlo con una forchetta e un filo d’olio e lasciarlo raffreddare.", "Aggiungere il cetriolo, i pomodori, la cipolla e il peperone.", "Condire con succo di limone, olio, sale, pepe, menta e prezzemolo tritati. Servire fresco."]),
    "bouye": ("Bouye (succo di baobab)", "Senegal", "15 min (+ 1 h in frigo)", "6 persone",
        "La polpa del frutto del baobab sciolta in una bevanda cremosa, dolce e acidula, servita ben fredda.",
        ["200 g di polvere di frutto di baobab e 1 litro di acqua fredda", "250 ml di latte condensato (o 150 g di zucchero)", "Zucchero a piacere", "1 bustina di zucchero vanigliato", "Acqua di fiori d’arancio o un pizzico di noce moscata (facoltativo)"],
        ["Stemperare la polvere di baobab in metà dell’acqua fredda e lasciar riposare 15 minuti.", "Mescolare bene per sciogliere la polpa, poi filtrare con un colino fine.", "Aggiungere il resto dell’acqua, il latte condensato, lo zucchero e lo zucchero vanigliato.", "Profumare con un po’ di acqua di fiori d’arancio o di noce moscata.", "Mettere in frigorifero 1 ora e servire ben fresco."]),
    "gboma-dessi": ("Gboma dessi", "Togo e Ghana", "1 h", "6 persone",
        "Lo stufato di spinaci del Togo: foglie di gboma cotte in salsa di pomodoro all’olio di palma, con carne e pesce affumicato.",
        ["1 kg di spinaci (gboma), freschi o surgelati", "500 g di manzo a pezzi", "1 pesce affumicato e 2 cucchiai di gamberetti secchi macinati", "3 pomodori, 2 cipolle, 1 cucchiaio di concentrato di pomodoro", "100 ml di olio di palma, peperoncino, zenzero, 1 dado, sale"],
        ["Cuocere la carne con una cipolla, lo zenzero, il dado e il sale in poca acqua per 30 minuti.", "Rosolare l’altra cipolla nell’olio di palma, aggiungere i pomodori frullati, il concentrato e il peperoncino; cuocere 10 minuti.", "Aggiungere la carne con il brodo, il pesce sbriciolato e i gamberetti; cuocere 10 minuti.", "Lavare e tritare gli spinaci, strizzarli e aggiungerli alla salsa.", "Cuocere 10 minuti senza coperchio. Servire con akoumé (pasta di mais), riso o igname."]),
    "to-sauce-gombo": ("Tô con salsa di gombo", "Burkina Faso e Mali", "1 h", "6 persone",
        "La pasta di miglio del Burkina e del Mali, soda e liscia, con una salsa filante di gombo, carne e soumbala.",
        ["500 g di farina di miglio o di sorgo (o di mais)", "500 g di gombo fresco o 3 cucchiai di gombo in polvere", "500 g di manzo o di montone a pezzi", "1 cucchiaio di soumbala (o 1 dado)", "2 pomodori, 1 cipolla, peperoncino, sale"],
        ["Salsa: cuocere la carne con la cipolla, i pomodori, il soumbala e il sale in 1 litro d’acqua per 40 minuti.", "Aggiungere il gombo tagliato (o la polvere) e il peperoncino; cuocere 15 minuti mescolando finché la salsa fila.", "Tô: stemperare un terzo della farina in 500 ml di acqua fredda, versarla in 1 litro di acqua bollente e cuocere 10 minuti mescolando.", "Togliere una ciotola di questa pappa, poi aggiungere il resto della farina a pioggia mescolando con forza con una spatola; ammorbidire con la pappa tenuta da parte se è troppo soda.", "Coprire 5 minuti a fuoco basso, formare delle palle in una ciotola bagnata e servire con la salsa."]),
    "banku-okro": ("Banku con zuppa di gombo", "Ghana", "1 h", "6 persone",
        "Il banku ghanese, una pasta leggermente acidula di mais e manioca fermentati, con zuppa di gombo al pesce.",
        ["1 kg di banku mix (pasta di mais e manioca)", "300 g di gombo", "500 g di pesce (tilapia o sgombro) o di manzo", "3 pomodori, 2 cipolle, peperoncino, zenzero", "2 cucchiai di gamberetti secchi macinati, 100 ml di olio di palma, 1 dado, sale"],
        ["Banku: stemperare la pasta in circa 750 ml di acqua salata finché è liscia.", "Cuocerla a fuoco medio mescolando senza sosta con una spatola per 20 minuti, finché è densa e liscia; formare delle palle.", "Zuppa: rosolare una cipolla nell’olio di palma, aggiungere i pomodori frullati con l’altra cipolla, lo zenzero e il peperoncino; cuocere 10 minuti.", "Aggiungere 500 ml d’acqua, il pesce, i gamberetti e il dado; cuocere 10 minuti.", "Aggiungere il gombo a rondelle e cuocere 8 minuti. Servire con il banku."]),
    "ngai-ngai": ("Ngai-ngai con pesce salato", "RD del Congo e Congo", "1 h (+ 2 h di ammollo)", "6 persone",
        "Le foglie acidule di karkadè (ngai-ngai) cotte nell’olio di palma con pesce salato: un classico di Kinshasa e Brazzaville.",
        ["500 g di foglie di karkadè (ngai-ngai), fresche o surgelate", "300 g di pesce salato", "100 ml di olio di palma", "2 melanzane piccole (facoltativo)", "2 cipolle, 2 spicchi d’aglio, peperoncino, sale"],
        ["Mettere a bagno il pesce salato per 2 ore cambiando l’acqua, poi sbriciolarlo.", "Lavare le foglie, tritarle e cuocerle 15 minuti in poca acqua; scolarle strizzandole.", "Rosolare le cipolle e l’aglio nell’olio di palma.", "Aggiungere le foglie, il pesce, le melanzane a cubetti e il peperoncino; cuocere 25 minuti a fuoco basso.", "Assaggiare prima di salare, il pesce è già salato. Servire con chikwangue, fufu o riso."]),
    "sorrel": ("Sorrel (bevanda di Natale)", "Giamaica", "30 min (+ 1 notte di infusione)", "8 persone",
        "La bevanda rosso rubino del Natale giamaicano: calici di karkadè in infusione con molto zenzero e spezie, serviti ben freddi.",
        ["2 tazze di calici di karkadè essiccati (sorrel)", "1 grosso pezzo di zenzero grattugiato e 2 litri d’acqua", "6 chiodi di garofano, 1 stecca di cannella, qualche grano di pimento", "1 tazza di zucchero", "Succo di lime; un goccio di rum (facoltativo, per gli adulti)"],
        ["Sciacquare i calici.", "Portare l’acqua a ebollizione con lo zenzero, i chiodi di garofano, la cannella e il pimento.", "Aggiungere il sorrel, spegnere il fuoco e lasciare in infusione una notte, coperto.", "Filtrare, zuccherare e aggiungere succo di lime a piacere.", "Servire con ghiaccio, con un goccio di rum per gli adulti."]),
    "mayi-moulen": ("Mayi moulen con sòs pwa", "Haiti", "40 min", "4 persone",
        "La farina di mais haitiana, cotta come una polenta cremosa e servita con una salsa di fagioli (sòs pwa).",
        ["2 tazze di farina di mais media (mayi moulen)", "1 scatola di fagioli rossi o neri", "1 tazza di latte di cocco (facoltativo)", "2 cucchiai di epis (condimento haitiano), timo, 2 chiodi di garofano", "1 cipolla, 2 cucchiai d’olio, sale"],
        ["Sòs pwa: frullare i fagioli con il loro liquido e scaldarli con metà dell’epis, il timo e i chiodi di garofano per 15 minuti, finché la salsa si addensa.", "Rosolare la cipolla e il resto dell’epis nell’olio, aggiungere 4 tazze d’acqua (o acqua e latte di cocco) e il sale; portare a ebollizione.", "Versare la farina di mais a pioggia mescolando senza sosta.", "Coprire e cuocere 20 minuti a fuoco bassissimo, mescolando di tanto in tanto, finché il mais è tenero.", "Servire il mayi moulen coperto di sòs pwa, con aringa affumicata o avocado."]),
}
